#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    // Read n and k from input
    long long n, k;
    if(!(cin >> n >> k)) {
        return 0;
    }

    // Cache for queried values: cache[x][y] = value at position (x,y)
    // Using 1-indexed coordinates as per problem
    vector<vector<long long>> cache(n + 1, vector<long long>(n + 1, -1));

    auto query = [&](int x, int y) -> long long {
        if(x < 1 || x > n || y < 1 || y > n) {
            cerr << "Invalid query: " << x << " " << y << endl;
            return -1;
        }
        if(cache[x][y] == -1) {
            cout << "QUERY " << x << " " << y << endl;
            long long val;
            cin >> val;
            cache[x][y] = val;
        }
        return cache[x][y];
    };

    // Count elements <= val in the sorted matrix
    // Starting from top-right corner, traverse in O(n)
    auto countLessEqual = [&](long long val) -> long long {
        long long count = 0;
        int row = 1;
        int col = n;
        while(row <= n && col >= 1) {
            long long curr = query(row, col);
            if(curr <= val) {
                // All elements from (row, 1) to (row, col) are <= val
                count += col;
                row++;
            } else {
                col--;
            }
        }
        return count;
    };

    // Binary search on value range [0, 10^18]
    long long lo = 0;
    long long hi = (long long)1e18;
    long long answer = 0;

    while(lo <= hi) {
        long long mid = lo + (hi - lo) / 2;
        long long cnt = countLessEqual(mid);

        if(cnt >= k) {
            answer = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }

    cout << "DONE " << answer << endl;

    return 0;
}
